import cairosvg
OUT_SVG="/sessions/happy-optimistic-pasteur/mnt/outputs/presets/svg"
OUT_PNG="/sessions/happy-optimistic-pasteur/mnt/outputs/presets/png"
INK="#241E17"; SEP="#9C8460"; OX="#8E3B2E"; OCH="#C8893A"; PET="#1C5D6E"
def H(inner): return f'<g stroke="{SEP}" stroke-width="2" opacity="0.6">{inner}</g>'
def hatch(x,y,w,h,n=6,dx=-22):
    s=""; step=h/n
    for i in range(n+1): s+=f'<line x1="{x}" y1="{y+i*step:.0f}" x2="{x+dx}" y2="{y+i*step+abs(dx):.0f}"/>'
    return H(s)
def wrap(name,inner):
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400">{inner}</svg>'
    open(f"{OUT_SVG}/{name}.svg","w").write(svg)
    cairosvg.svg2png(url=f"{OUT_SVG}/{name}.svg",write_to=f"{OUT_PNG}/{name}.png",output_width=400,output_height=400)
    print("ok",name)
